insert into sports (id, name) values
  ('sport-muaythai', '{"en":"Muay Thai","pt":"Muay Thai"}')
insert into modules (id, name, description, position_type, default_order) values
  ('mt-stance', 'Stance & Footwork', 'Stances, guards and footwork fundamentals.', 'footwork', 1),
  ('mt-punch', 'Punches', 'Fist techniques.', 'punch', 2),
  ('mt-elbow', 'Elbows', 'Elbow strikes.', 'elbow', 3),
  ('mt-kick', 'Kicks', 'Kicking techniques.', 'kick', 4),
  ('mt-knee', 'Knees', 'Knee strikes.', 'knee', 5),
  ('mt-clinch', 'Clinch', 'Clinch grips, position, knees and throws.', 'clinch', 6),
  ('mt-defense', 'Defense', 'Blocks, slips, parries and evasions.', 'defense', 7),
  ('mt-counter', 'Counter-Attack', 'Counters to strikes and clinch.', 'counter', 8),
  ('mt-concepts', 'Concepts', 'Strategy, scoring, rhythm and culture.', 'concept', 9),
  ('mt-drills', 'Drills', 'Solo, partner and conditioning drills.', 'drill', 10)
insert into techniques (id, number, category, type, name, slug, description, complexity, key_details, ruleset, context, leg_lock_tier, wrestling_dependency, default_module_id, sport_id) values
  ('tech-mt-001', 1, 'Stance & Footwork', 'Stance', 'Orthodox Fighting Stance', 'mt-orthodox-fighting-stance', 'Weight distributed 60/40 rear/front, lead foot 45°, rear foot 90°, hands up protecting jaw, chin down.', 'Beginner', 'Elbows protect ribs. Error: standing square — opens body and removes power from cross.', 'Both', 'Both', 'None', false, 'mt-stance', 'sport-muaythai'),
  ('tech-mt-002', 2, 'Stance & Footwork', 'Stance', 'Southpaw Fighting Stance', 'mt-southpaw-fighting-stance', 'Mirror of orthodox: right foot leads, left hand is power hand. Creates open-stance matchup against orthodox fighters.', 'Beginner', 'Even orthodox fighters should drill southpaw basics for stance switching.', 'Both', 'Both', 'None', false, 'mt-stance', 'sport-muaythai'),
  ('tech-mt-003', 3, 'Stance & Footwork', 'Stance', 'High Guard (Dutch Style)', 'mt-high-guard-dutch-style', 'Fists held tight to temples, elbows narrow, absorbs head shots while countering.', 'Intermediate', 'Sacrifices vision slightly. Suited for aggressive pressure fighters.', 'Both', 'Both', 'None', false, 'mt-stance', 'sport-muaythai'),
  ('tech-mt-004', 4, 'Stance & Footwork', 'Footwork', 'Step Forward', 'mt-step-forward', 'Advance by stepping lead foot first, rear foot follows — maintaining stance width.', 'Beginner', 'Never let feet come together mid-step. Error: hopping rather than stepping — kills base.', 'Both', 'Both', 'None', false, 'mt-stance', 'sport-muaythai'),
  ('tech-mt-005', 5, 'Stance & Footwork', 'Footwork', 'Step Back', 'mt-step-back', 'Retreat by moving rear foot first, lead follows. Maintains fighting stance throughout.', 'Beginner', 'Mirror of step forward. Common error: crossing feet when retreating quickly.', 'Both', 'Both', 'None', false, 'mt-stance', 'sport-muaythai'),
  ('tech-mt-006', 6, 'Stance & Footwork', 'Footwork', 'Lateral Step (Left/Right)', 'mt-lateral-step-left-right', 'Slide sideways maintaining stance width — lead foot leads when going lead side, rear foot leads going rear side.', 'Beginner', 'Stay balanced throughout. Error: stepping feet together — creates vulnerable moment.', 'Both', 'Both', 'None', false, 'mt-stance', 'sport-muaythai'),
  ('tech-mt-007', 7, 'Stance & Footwork', 'Footwork', '45-Degree Angle Step', 'mt-45-degree-angle-step', 'Step offline at 45 degrees to either side to avoid an attack and create a counter angle.', 'Intermediate', 'Fundamental defensive footwork. Step toward the outside of opponent''s attack when possible.', 'Both', 'Both', 'None', false, 'mt-stance', 'sport-muaythai'),
  ('tech-mt-008', 8, 'Stance & Footwork', 'Footwork', 'Semi-Circle Step', 'mt-semi-circle-step', 'Larger arc step (180°) to completely reposition relative to opponent — used to change angle drastically.', 'Intermediate', 'Used when 45° is insufficient. Requires good balance mid-arc.', 'Both', 'Both', 'None', false, 'mt-stance', 'sport-muaythai'),
  ('tech-mt-009', 9, 'Stance & Footwork', 'Footwork', 'Switch Step (Stance Switch)', 'mt-switch-step-stance-switch', 'Briefly switch stance by swapping feet — used to load the left kick, change angle, or confuse opponent.', 'Intermediate', 'Keep hands up during switch. Error: pausing in the switch — telegraphs the kick.', 'Both', 'Sport', 'None', false, 'mt-stance', 'sport-muaythai'),
  ('tech-mt-010', 10, 'Stance & Footwork', 'Footwork', 'Lateral Circling (Outside)', 'mt-lateral-circling-outside', 'Circle continuously to the outside of opponent''s lead hand — removes their power hand from the equation.', 'Intermediate', 'Circle away from rear hand. Against southpaw: circle to your right (their weak side).', 'Both', 'Sport', 'None', false, 'mt-stance', 'sport-muaythai'),
  ('tech-mt-011', 11, 'Stance & Footwork', 'Footwork', 'Ring Cutting', 'mt-ring-cutting', 'Use angles and forward pressure to trap opponent against the ropes or in a corner.', 'Advanced', 'Requires reading opponent''s retreat pattern. Cut off escape early — don''t chase straight.', 'Professional', 'Sport', 'None', false, 'mt-stance', 'sport-muaythai'),
  ('tech-mt-012', 12, 'Stance & Footwork', 'Footwork', 'Orthodox vs. Southpaw Adjustment', 'mt-orthodox-vs-southpaw-adjustment', 'Specific footwork adjustments when facing a southpaw: lead foot outside, jab to outside, left kick to open side.', 'Advanced', 'Most common skill gap. Train this systematically — don''t wait for sparring to figure it out.', 'Both', 'Sport', 'None', false, 'mt-stance', 'sport-muaythai'),
  ('tech-mt-013', 13, 'Fist Technique', 'Straight', 'Jab (Mat Throng Lead)', 'mt-jab-mat-throng-lead', 'Lead hand straight punch — short, fast, used to measure distance, set up combinations, and disrupt rhythm.', 'Beginner', 'Snap back immediately. Error: dropping rear hand when jabbing — leaves jaw exposed.', 'Both', 'Both', 'None', false, 'mt-punch', 'sport-muaythai'),
  ('tech-mt-014', 14, 'Fist Technique', 'Straight', 'Cross (Mat Throng Rear)', 'mt-cross-mat-throng-rear', 'Rear hand straight punch — primary power punch. Hip and shoulder rotate to generate force.', 'Beginner', 'Drive rear hip forward. Error: arm punch with no hip rotation — loses 60% of power.', 'Both', 'Both', 'None', false, 'mt-punch', 'sport-muaythai'),
  ('tech-mt-015', 15, 'Fist Technique', 'Hook', 'Side Hook (Mat Wiang)', 'mt-side-hook-mat-wiang', 'Horizontal arc punch targeting jaw or body. Elbow at 90°, rotation comes from hip and shoulder pivot.', 'Beginner', 'Keep elbow at shoulder height for head hook. Error: dropping elbow — becomes a slap.', 'Both', 'Both', 'None', false, 'mt-punch', 'sport-muaythai'),
  ('tech-mt-016', 16, 'Fist Technique', 'Uppercut', 'Uppercut (Mat Ngad)', 'mt-uppercut-mat-ngad', 'Vertical punch driving upward under guard targeting chin or solar plexus.', 'Beginner', 'Drive from legs and hips. Error: winding back — telegraphs the punch.', 'Both', 'Both', 'None', false, 'mt-punch', 'sport-muaythai'),
  ('tech-mt-017', 17, 'Fist Technique', 'Overhead', 'Overhead Punch (Mat Kong)', 'mt-overhead-punch-mat-kong', 'Looping downward punch thrown over opponent''s guard — targets top of head or nose.', 'Intermediate', 'Useful when opponent tucks chin and ducks. Error: over-committing and losing balance.', 'Both', 'Both', 'None', false, 'mt-punch', 'sport-muaythai'),
  ('tech-mt-018', 18, 'Fist Technique', 'Hook', 'Swing (Mat Weang Yao)', 'mt-swing-mat-weang-yao', 'Wide horizontal arc punch — longer range than standard hook, less power, targets temples.', 'Intermediate', 'Sacrifice power for reach. Error: telegraphing with shoulder dip before throwing.', 'Both', 'Sport', 'None', false, 'mt-punch', 'sport-muaythai'),
  ('tech-mt-019', 19, 'Fist Technique', 'Spinning', 'Spinning Back Fist (Mat Weang Glab)', 'mt-spinning-back-fist-mat-weang-glab', 'Spin 180° and strike with rear-hand knuckles to jaw or temple.', 'Advanced', 'Keep eyes on target through spin. Error: losing sight of opponent — telegraphed and easy to counter.', 'Professional', 'Sport', 'None', false, 'mt-punch', 'sport-muaythai'),
  ('tech-mt-020', 20, 'Fist Technique', 'Jumping', 'Flying Punch (Gra Dod Chok)', 'mt-flying-punch-gra-dod-chok', 'Jump and switch guard mid-air, landing cross or hook as lead hand changes.', 'Advanced', 'Rarely used as primary attack — element of surprise only. Requires good timing and athleticism.', 'Professional', 'Sport', 'None', false, 'mt-punch', 'sport-muaythai'),
  ('tech-mt-021', 21, 'Elbow Technique', 'Horizontal', 'Rotating/Horizontal Elbow (Sok Tee)', 'mt-rotating-horizontal-elbow-sok-tee', 'Horizontal elbow swing striking with the point — targets temple, jaw, or bridge of nose.', 'Intermediate', 'Most common elbow. Pivot from hip. Error: throwing with arm only — loses power and accuracy.', 'Professional', 'Both', 'None', false, 'mt-elbow', 'sport-muaythai'),
  ('tech-mt-022', 22, 'Elbow Technique', 'Diagonal', 'Side/Diagonal Elbow (Sok Tad)', 'mt-side-diagonal-elbow-sok-tad', 'Diagonal elbow strike (45° downward or upward) targeting jaw, nasal bone, or eyebrow.', 'Intermediate', 'Drive through the target, not at it. Entry from clinch range or after slipping a punch.', 'Professional', 'Both', 'None', false, 'mt-elbow', 'sport-muaythai'),
  ('tech-mt-023', 23, 'Elbow Technique', 'Uppercut', 'Uppercut Elbow (Sok Ngad)', 'mt-uppercut-elbow-sok-ngad', 'Upward elbow driving under opponent''s guard targeting chin — mirrors the uppercut punch.', 'Intermediate', 'Keep elbow tight on the way up. Works when opponent''s guard is high or they lean forward.', 'Professional', 'Both', 'None', false, 'mt-elbow', 'sport-muaythai'),
  ('tech-mt-024', 24, 'Elbow Technique', 'Downward', 'Spear/Downward Elbow (Sok Pung)', 'mt-spear-downward-elbow-sok-pung', 'Elbow drops vertically downward onto top of head or nasal bone — requires height advantage or clinch position.', 'Advanced', 'Devastating from clinch when controlling head. Error: reaching down instead of driving weight through.', 'Professional', 'Sport', 'None', false, 'mt-elbow', 'sport-muaythai'),
  ('tech-mt-025', 25, 'Elbow Technique', 'Reverse', 'Reverse Elbow (Sok Kratung)', 'mt-reverse-elbow-sok-kratung', 'Backward-driving elbow using the rear face of the elbow joint — targets chin or ribs stepping past opponent.', 'Advanced', 'Works when stepping to outside. Requires precise angle — difficult to land cleanly.', 'Professional', 'Sport', 'None', false, 'mt-elbow', 'sport-muaythai'),
  ('tech-mt-026', 26, 'Elbow Technique', 'Spinning', 'Spinning Elbow (Sok Glab)', 'mt-spinning-elbow-sok-glab', 'Full 360° spin strike with elbow — targets temple or jaw as opponent steps into range.', 'Advanced', 'High risk — full spin leaves back exposed. Best used as a counter or surprise.', 'Professional', 'Sport', 'None', false, 'mt-elbow', 'sport-muaythai'),
  ('tech-mt-027', 27, 'Elbow Technique', 'Downward', 'Elbow from Above (Sok Sub)', 'mt-elbow-from-above-sok-sub', 'Diagonal downward elbow driving forward-and-down — targets head or collar bone in close range.', 'Advanced', 'Requires inside clinch position. Drive from shoulder, not just arm.', 'Professional', 'Sport', 'None', false, 'mt-elbow', 'sport-muaythai'),
  ('tech-mt-028', 28, 'Elbow Technique', 'Jumping', 'Flying Elbow (Gra Dog Sok)', 'mt-flying-elbow-gra-dog-sok', 'Jump and drive elbow downward onto opponent''s head — spectacular but high risk.', 'Expert', 'Requires significant height advantage or opponent''s posture being broken forward. Rare in modern competition.', 'Professional', 'Sport', 'None', false, 'mt-elbow', 'sport-muaythai'),
  ('tech-mt-029', 29, 'Kick Technique', 'Round Kick', 'Round Kick to Head (Te Tad Hua)', 'mt-round-kick-to-head-te-tad-hua', 'High roundhouse kick driving shin into temple or jaw. Requires hip flexibility and full hip rotation.', 'Intermediate', 'Hip must fully turn over — kick with hip, not just leg. Error: kicking with the foot instead of shin.', 'Both', 'Sport', 'None', false, 'mt-kick', 'sport-muaythai'),
  ('tech-mt-030', 30, 'Kick Technique', 'Round Kick', 'Round Kick to Body (Te Tad Tua)', 'mt-round-kick-to-body-te-tad-tua', 'Roundhouse kick driving shin into ribs or liver — most common and highest-percentage Muay Thai technique.', 'Beginner', 'Land with shin, not foot or ankle. Pivot supporting foot fully. Error: not pivoting — kills range and power.', 'Both', 'Both', 'None', false, 'mt-kick', 'sport-muaythai'),
  ('tech-mt-031', 31, 'Kick Technique', 'Low Kick', 'Leg Kick / Low Kick (Te Tad Lang)', 'mt-leg-kick-low-kick-te-tad-lang', 'Roundhouse kick targeting outer or inner thigh — accumulates damage and compromises opponent''s base.', 'Beginner', 'Check (shin block) is the primary defense. Aim at mid-thigh, not knee. Error: kicking to calf — less effective.', 'Both', 'Both', 'None', false, 'mt-kick', 'sport-muaythai'),
  ('tech-mt-032', 32, 'Kick Technique', 'Low Kick', 'Inside Low Kick (Te Tad Nai)', 'mt-inside-low-kick-te-tad-nai', 'Roundhouse kick targeting inner thigh — delivered from shorter range than outer low kick.', 'Intermediate', 'Requires opening in stance or opponent stepping forward. Often set up by body feint.', 'Both', 'Both', 'None', false, 'mt-kick', 'sport-muaythai'),
  ('tech-mt-033', 33, 'Kick Technique', 'Push Kick', 'Front Teep (Teep Trong)', 'mt-front-teep-teep-trong', 'Front push kick using ball of foot — maintains distance, disrupts opponent''s rhythm, scores in competition.', 'Beginner', 'Push through target, not at it. Extend hip to full length. Error: bending knee on contact — becomes a tap.', 'Both', 'Both', 'None', false, 'mt-kick', 'sport-muaythai'),
  ('tech-mt-034', 34, 'Kick Technique', 'Push Kick', 'Leg Teep (Teep Robgaun)', 'mt-leg-teep-teep-robgaun', 'Push kick targeting the knee or thigh — used to compromise opponent''s base or disrupt their stance.', 'Intermediate', 'Useful against aggressive forwards. Target the lead knee to check their advance.', 'Both', 'Sport', 'None', false, 'mt-kick', 'sport-muaythai'),
  ('tech-mt-035', 35, 'Kick Technique', 'Push Kick', 'Side Teep (Teep Khang)', 'mt-side-teep-teep-khang', 'Lateral push kick using the heel — targets stomach or hip to redirect opponent''s movement.', 'Intermediate', 'Requires more flexibility than front teep. Best when opponent is attacking at an angle.', 'Both', 'Both', 'None', false, 'mt-kick', 'sport-muaythai'),
  ('tech-mt-036', 36, 'Kick Technique', 'Push Kick', 'Back Teep (Teep Glap Lang)', 'mt-back-teep-teep-glap-lang', 'Spinning push kick using heel — delivered after 180° turn, targets stomach.', 'Advanced', 'Head must fully turn to find target before kick lands. Error: spinning blind — easily countered.', 'Both', 'Sport', 'None', false, 'mt-kick', 'sport-muaythai'),
  ('tech-mt-037', 37, 'Kick Technique', 'Axe Kick', 'Heel Kick from Above (Te Kook)', 'mt-heel-kick-from-above-te-kook', 'Raising straight leg high and driving heel downward onto opponent''s head or collar bone.', 'Advanced', 'Requires high flexibility. Best when opponent ducks forward. Error: not raising leg high enough to create downward arc.', 'Both', 'Sport', 'None', false, 'mt-kick', 'sport-muaythai'),
  ('tech-mt-038', 38, 'Kick Technique', 'Spinning', 'Spinning Heel Kick (Chorake Faad Hang)', 'mt-spinning-heel-kick-chorake-faad-hang', 'Full 360° spin targeting temple with heel — the ''crocodile tail'' kick.', 'Advanced', 'Requires precise timing and distance. Train exit footwork after kick to avoid counter.', 'Professional', 'Sport', 'None', false, 'mt-kick', 'sport-muaythai'),
  ('tech-mt-039', 39, 'Kick Technique', 'Hook Kick', 'Hook Kick', 'mt-hook-kick', 'Extends leg forward then hooks heel back toward target — unpredictable trajectory targets temple.', 'Advanced', 'Misleading trajectory is its advantage. Requires hip flexibility and good distance control.', 'Both', 'Sport', 'None', false, 'mt-kick', 'sport-muaythai'),
  ('tech-mt-040', 40, 'Kick Technique', 'Half-Shin', 'Half-Shin Half-Knee (Te Khrueng Khaeng)', 'mt-half-shin-half-knee-te-khrueng-khaeng', 'Mid-height kick landing on the shin-knee junction — targets stomach, chest, or ribs.', 'Intermediate', 'Shorter range than full round kick. Error: over-rotating and losing balance when opponent steps back.', 'Both', 'Both', 'None', false, 'mt-kick', 'sport-muaythai'),
  ('tech-mt-041', 41, 'Kick Technique', 'Jumping', 'Jumping Round Kick (Gra Dod Te)', 'mt-jumping-round-kick-gra-dod-te', 'Leap and deliver roundhouse kick — adds height and changes attack angle unpredictably.', 'Advanced', 'Commit fully — hesitation mid-jump is dangerous. Best used as a surprise counter.', 'Professional', 'Sport', 'None', false, 'mt-kick', 'sport-muaythai'),
  ('tech-mt-042', 42, 'Kick Technique', 'Jumping', 'Jumping Push Kick (Gra Dod Teep)', 'mt-jumping-push-kick-gra-dod-teep', 'Leap and extend front kick — covers distance rapidly and targets solar plexus or chin.', 'Advanced', 'Requires good timing and athleticism. Error: jumping too early — opponent steps back and counters landing.', 'Professional', 'Sport', 'None', false, 'mt-kick', 'sport-muaythai'),
  ('tech-mt-043', 43, 'Knee Technique', 'Straight Knee', 'Straight Knee (Khow Throng)', 'mt-straight-knee-khow-throng', 'Drive rear or lead knee forward and upward into opponent''s solar plexus or chin as they lean in.', 'Beginner', 'Pull opponent''s head down into knee with collar/neck grip. Without the pull, range is difficult to find.', 'Both', 'Both', 'None', false, 'mt-knee', 'sport-muaythai'),
  ('tech-mt-044', 44, 'Knee Technique', 'Diagonal Knee', 'Diagonal Knee (Khow Chiang)', 'mt-diagonal-knee-khow-chiang', 'Knee driven at 45° angle into opponent''s ribs — harder to defend than straight knee.', 'Intermediate', 'Drive from the hip. Often follows clinch entry or jab-cross combination to close range.', 'Both', 'Both', 'None', false, 'mt-knee', 'sport-muaythai'),
  ('tech-mt-045', 45, 'Knee Technique', 'Round Knee', 'Round Knee (Khow Kong)', 'mt-round-knee-khow-kong', 'Circular knee strike similar to roundhouse kick motion — targets ribs or thigh.', 'Intermediate', 'Less common at distance; more effective from clinch. Drive hip through target.', 'Both', 'Sport', 'None', false, 'mt-knee', 'sport-muaythai'),
  ('tech-mt-046', 46, 'Knee Technique', 'Jumping Knee', 'Flying Knee (Khow Loy)', 'mt-flying-knee-khow-loy', 'Run or step in and leap, driving knee forward into opponent''s face or solar plexus.', 'Advanced', 'One of Muay Thai''s most iconic techniques. Commit to full flight — half-attempts land badly. Set up with teep to close distance.', 'Both', 'Both', 'None', false, 'mt-knee', 'sport-muaythai'),
  ('tech-mt-047', 47, 'Knee Technique', 'Jumping Knee', 'Knee Bomb (Khow Yon)', 'mt-knee-bomb-khow-yon', 'Jump and drive knee downward onto opponent — used when opponent is bent forward or ducking.', 'Advanced', 'Requires opponent''s posture to be broken forward. Error: jumping when opponent is upright — misses entirely.', 'Professional', 'Sport', 'None', false, 'mt-knee', 'sport-muaythai'),
  ('tech-mt-048', 48, 'Clinch', 'Grip', 'Double Collar Tie (Plam)', 'mt-double-collar-tie-plam', 'Both hands clasped behind opponent''s neck — the dominant clinch position for knee strikes.', 'Beginner', 'Pull head down and toward your centerline. Elbows in to break opponent''s grip attempts.', 'Both', 'Both', 'None', false, 'mt-clinch', 'sport-muaythai'),
  ('tech-mt-049', 49, 'Clinch', 'Grip', 'Single Collar Tie', 'mt-single-collar-tie', 'One hand behind neck, one hand controlling opposite arm or ribs.', 'Beginner', 'More mobile than double collar; good for transitions. Error: leaving collar arm loose — easy to strip.', 'Both', 'Both', 'None', false, 'mt-clinch', 'sport-muaythai'),
  ('tech-mt-050', 50, 'Clinch', 'Grip', 'Diagonal Clinch Grip', 'mt-diagonal-clinch-grip', 'One hand grips neck, other grips diagonal collar — controls opponent''s rotation for knee angles.', 'Intermediate', 'Enables diagonal knee more easily than double collar. Transition from double collar.', 'Both', 'Sport', 'None', false, 'mt-clinch', 'sport-muaythai'),
  ('tech-mt-051', 51, 'Clinch', 'Grip', 'Body Lock', 'mt-body-lock', 'Both arms wrap opponent''s torso — used for throws, sweeps, and clinch control.', 'Intermediate', 'Releases upper body for opponent''s elbow attacks. Use briefly for throw setups.', 'Both', 'Both', 'None', false, 'mt-clinch', 'sport-muaythai'),
  ('tech-mt-052', 52, 'Clinch', 'Position', 'Inside Position (Neck Wrestling)', 'mt-inside-position-neck-wrestling', 'Securing inside position with elbows between opponent''s arms — controls the clinch battle.', 'Intermediate', 'Whoever has inside controls the clinch. Constant battle to achieve this. Error: giving both elbows outside — opponent controls completely.', 'Both', 'Both', 'None', false, 'mt-clinch', 'sport-muaythai'),
  ('tech-mt-053', 53, 'Clinch', 'Position', 'Outside Position', 'mt-outside-position', 'Arms outside opponent''s in the clinch — defensive position; work to recover inside immediately.', 'Intermediate', 'From outside: attack with arms and body to create space to reenter. Avoid knees from here.', 'Both', 'Both', 'None', false, 'mt-clinch', 'sport-muaythai'),
  ('tech-mt-054', 54, 'Clinch', 'Entry', 'Clinch Entry', 'mt-clinch-entry', 'Closing distance from punching range to clinch — tie up after a combination, after eating a punch, or as primary tactic.', 'Intermediate', 'Cover up and walk through to avoid strikes on the way in. Head position matters — don''t lead with chin.', 'Both', 'Both', 'None', false, 'mt-clinch', 'sport-muaythai'),
  ('tech-mt-055', 55, 'Clinch', 'Breaking', 'Clinch Breaking', 'mt-clinch-breaking', 'Legally escaping a clinch: push opponent away, step outside and pull, or use referee break.', 'Intermediate', 'In competition, controlling clinch breaks scores. Error: breaking wildly — creates counter opportunity.', 'Both', 'Sport', 'None', false, 'mt-clinch', 'sport-muaythai'),
  ('tech-mt-056', 56, 'Clinch', 'Knee', 'Straight Knee in Clinch (Khow Throng)', 'mt-straight-knee-in-clinch-khow-throng', 'Drive knee forward into stomach or solar plexus while pulling opponent''s head down in double collar.', 'Beginner', 'Pull head down to meet rising knee. Alternate knees. Error: releasing grip before impact.', 'Both', 'Both', 'None', false, 'mt-clinch', 'sport-muaythai'),
  ('tech-mt-057', 57, 'Clinch', 'Knee', 'Diagonal Knee in Clinch (Khow Chiang)', 'mt-diagonal-knee-in-clinch-khow-chiang', 'Drive knee at 45° into ribs while rotating collar grip to expose the angle.', 'Intermediate', 'Rotate grip to open rib angle before driving knee. Harder to shield than straight knee.', 'Both', 'Sport', 'None', false, 'mt-clinch', 'sport-muaythai'),
  ('tech-mt-058', 58, 'Clinch', 'Knee', 'Round Knee in Clinch (Khow Kong)', 'mt-round-knee-in-clinch-khow-kong', 'Circular knee into ribs or thigh in close quarters — used when straight and diagonal are defended.', 'Intermediate', 'Shift weight to supporting leg and drive hip. Often used as a third knee variation in combination.', 'Both', 'Sport', 'None', false, 'mt-clinch', 'sport-muaythai'),
  ('tech-mt-059', 59, 'Clinch', 'Knee', 'Short Knee (Khow Noi)', 'mt-short-knee-khow-noi', 'Very close-range upward knee when no room for full knee extension — targets solar plexus.', 'Advanced', 'Works in extremely tight clinch when opponent presses in. Drive from hip with short range.', 'Both', 'Sport', 'None', false, 'mt-clinch', 'sport-muaythai'),
  ('tech-mt-060', 60, 'Clinch', 'Knee', 'Knee from Above (Khow God)', 'mt-knee-from-above-khow-god', 'Downward knee driving onto opponent''s thigh when they bend forward.', 'Advanced', 'Requires opponent bent over. Common follow-up after pulling head down hard.', 'Professional', 'Sport', 'None', false, 'mt-clinch', 'sport-muaythai'),
  ('tech-mt-061', 61, 'Clinch', 'Throw', 'Dump Sweep (Hip Throw)', 'mt-dump-sweep-hip-throw', 'Use hip as fulcrum to sweep opponent off their feet from double collar.', 'Advanced', 'Step across, load opponent onto hip, drive through. Error: attempting with poor inside position — no leverage.', 'Both', 'Sport', 'None', false, 'mt-clinch', 'sport-muaythai'),
  ('tech-mt-062', 62, 'Clinch', 'Throw', 'Simple Foot Sweep', 'mt-simple-foot-sweep', 'Use inside or outside foot to sweep opponent''s supporting leg while disrupting their balance with collar control.', 'Advanced', 'Timing: sweep as weight shifts to target foot. Error: sweeping too early — foot has no weight on it.', 'Both', 'Sport', 'None', false, 'mt-clinch', 'sport-muaythai'),
  ('tech-mt-063', 63, 'Clinch', 'Throw', 'Rotative Sweep', 'mt-rotative-sweep', 'Use rotation and hip to sweep — opponent spun off balance and tripped.', 'Advanced', 'Requires commitment to rotation. Sets up when opponent resists clinch pressure.', 'Professional', 'Sport', 'None', false, 'mt-clinch', 'sport-muaythai'),
  ('tech-mt-064', 64, 'Clinch', 'Elbow', 'Clinch Elbow (Spear/Downward)', 'mt-clinch-elbow-spear-downward', 'Drive elbow downward onto opponent''s head or neck from inside clinch position.', 'Advanced', 'Most dangerous elbow variation. Requires dominant inside position. Error: reaching without securing position first.', 'Professional', 'Sport', 'None', false, 'mt-clinch', 'sport-muaythai'),
  ('tech-mt-065', 65, 'Clinch', 'Arm Trap', 'Arm Trapping', 'mt-arm-trapping', 'Control opponent''s arm in the clinch to remove it from the knee-defense equation.', 'Advanced', 'Trap the arm against your body, not with your hand. Frees knee angle on trapped-arm side.', 'Both', 'Sport', 'None', false, 'mt-clinch', 'sport-muaythai'),
  ('tech-mt-066', 66, 'Clinch', 'Defense', 'Clinch Defense: Step Outside and Pull', 'mt-clinch-defense-step-outside-and-pull', 'Break clinch by stepping to outside and pulling opponent off-balance as you exit.', 'Intermediate', 'Creates counter-attack opportunity as opponent stumbles. Error: pulling without stepping — opponent follows.', 'Both', 'Both', 'None', false, 'mt-clinch', 'sport-muaythai'),
  ('tech-mt-067', 67, 'Clinch', 'Defense', 'Clinch Defense: Push Away', 'mt-clinch-defense-push-away', 'Create space from clinch by driving forearms into opponent''s chest or biceps.', 'Beginner', 'Use full body extension, not just arms. Follow immediately with attack or re-establish stance.', 'Both', 'Both', 'None', false, 'mt-clinch', 'sport-muaythai'),
  ('tech-mt-068', 68, 'Defense', 'Block', 'Arm Shield Block', 'mt-arm-shield-block', 'Raise forearm vertically to block incoming punches — elbow down, fist at temple.', 'Beginner', 'Don''t reach out to block — keep tight. Error: blocking with open hand — wrist injury risk.', 'Both', 'Both', 'None', false, 'mt-defense', 'sport-muaythai'),
  ('tech-mt-069', 69, 'Defense', 'Block', 'Shin Block (Check)', 'mt-shin-block-check', 'Raise knee and turn shin to meet incoming low or round kick — absorbs the kick on the hardest part of your shin.', 'Beginner', 'The most important defensive technique in Muay Thai. Raise knee, don''t stomp down. Error: blocking with inside calf — painful and ineffective.', 'Both', 'Both', 'None', false, 'mt-defense', 'sport-muaythai'),
  ('tech-mt-070', 70, 'Defense', 'Block', 'Knee Block (Inside)', 'mt-knee-block-inside', 'Bring knee inward to block low kick targeting inner thigh.', 'Intermediate', 'Less versatile than shin check — specific to inside low kick. Error: twisting knee incorrectly — injury risk.', 'Both', 'Both', 'None', false, 'mt-defense', 'sport-muaythai'),
  ('tech-mt-071', 71, 'Defense', 'Block', 'Arm Block vs. Kick', 'mt-arm-block-vs-kick', 'Catch kick on crossed forearms or single forearm to reduce damage from body kicks.', 'Intermediate', 'Used when shin check is too slow. Elbow in tight. Error: catching on the elbow crease — ineffective.', 'Both', 'Both', 'None', false, 'mt-defense', 'sport-muaythai'),
  ('tech-mt-072', 72, 'Defense', 'Slip', 'Slip Outside (vs. Jab)', 'mt-slip-outside-vs-jab', 'Rotate head to outside of jab — head moves off centerline while body stays in range.', 'Intermediate', 'Move before the punch, not after. Creates counter angle for right cross. Error: moving backward instead of rotating.', 'Both', 'Both', 'None', false, 'mt-defense', 'sport-muaythai'),
  ('tech-mt-073', 73, 'Defense', 'Slip', 'Slip Inside (vs. Cross)', 'mt-slip-inside-vs-cross', 'Rotate head to inside of rear hand cross — risky but creates close-range counter opportunities.', 'Advanced', 'Higher risk than slipping outside. Better suited for experienced fighters who read the cross early.', 'Both', 'Sport', 'None', false, 'mt-defense', 'sport-muaythai'),
  ('tech-mt-074', 74, 'Defense', 'Lean', 'Lean Back (vs. Head Kick)', 'mt-lean-back-vs-head-kick', 'Sway torso backward from hips to take head out of range of incoming head kick.', 'Intermediate', 'Lean from hips, not just neck. Works for head kicks — not effective vs. body attacks. Error: leaning too far — balance lost for counter.', 'Both', 'Both', 'None', false, 'mt-defense', 'sport-muaythai'),
  ('tech-mt-075', 75, 'Defense', 'Lean', 'Pulling Leg Back vs. Low Kick', 'mt-pulling-leg-back-vs-low-kick', 'Retract lead leg by pulling weight back as opponent''s low kick arrives — removes the target.', 'Intermediate', 'Weight must shift first — leg pull follows. Error: just lifting the foot — opponent still reaches thigh.', 'Both', 'Both', 'None', false, 'mt-defense', 'sport-muaythai'),
  ('tech-mt-076', 76, 'Defense', 'Parry', 'Parry vs. Jab', 'mt-parry-vs-jab', 'Deflect incoming jab with open rear hand — redirects the punch offline.', 'Beginner', 'Light touch — redirect, don''t slap. Error: overextending the parry — opens your guard.', 'Both', 'Both', 'None', false, 'mt-defense', 'sport-muaythai'),
  ('tech-mt-077', 77, 'Defense', 'Parry', 'Parry vs. Cross', 'mt-parry-vs-cross', 'Deflect rear hand punch with lead hand — harder to time, more valuable.', 'Intermediate', 'Requires earlier read. Error: blocking too late — parry becomes a flinch.', 'Both', 'Both', 'None', false, 'mt-defense', 'sport-muaythai'),
  ('tech-mt-078', 78, 'Defense', 'Catch', 'Catch the Teep', 'mt-catch-the-teep', 'Use both hands to catch opponent''s front kick — creates sweep or throw opportunity.', 'Intermediate', 'Scoop kick, don''t grab. Step offline as you catch to reduce push force. Error: catching straight-on — pushed backward.', 'Both', 'Both', 'None', false, 'mt-defense', 'sport-muaythai'),
  ('tech-mt-079', 79, 'Defense', 'Catch', 'Catch the Round Kick', 'mt-catch-the-round-kick', 'Catch opponent''s body round kick under your arm — creates trip or clinch entry.', 'Advanced', 'Hard to time. Pin elbow tight onto shin. Error: catching at wrist level — poor control, hurts hand.', 'Both', 'Sport', 'None', false, 'mt-defense', 'sport-muaythai'),
  ('tech-mt-080', 80, 'Defense', 'Avoid', 'Dodge to Side', 'mt-dodge-to-side', 'Step at 45° angle while opponent throws — exits the attack line and creates counter angle.', 'Intermediate', 'Footwork-based defense. More efficient than leaning when combined with counter. Error: dodging straight back — remains on opponent''s centerline.', 'Both', 'Both', 'None', false, 'mt-defense', 'sport-muaythai'),
  ('tech-mt-081', 81, 'Defense', 'Active Defense', 'Counter-Attack as Defense (Kao Na)', 'mt-counter-attack-as-defense-kao-na', 'Attack simultaneously or immediately as opponent loads — interrupts their attack before it lands.', 'Advanced', 'Requires reading opponent''s preparation tells. The highest form of defense in Muay Thai.', 'Both', 'Sport', 'None', false, 'mt-defense', 'sport-muaythai'),
  ('tech-mt-082', 82, 'Counter-Attack', 'Kick Counter', 'Check Low Kick → Rear Round Kick', 'mt-check-low-kick-rear-round-kick', 'Shin check opponent''s low kick and immediately counter with rear leg round kick to the body or head.', 'Intermediate', 'Counter while opponent''s weight is on their kicking leg — prime moment of vulnerability.', 'Both', 'Both', 'None', false, 'mt-counter', 'sport-muaythai'),
  ('tech-mt-083', 83, 'Counter-Attack', 'Kick Counter', 'Catch Teep → Enter Clinch', 'mt-catch-teep-enter-clinch', 'Catch opponent''s front kick and use their forward commitment to pull them into clinch range.', 'Intermediate', 'Control the caught leg as you step in. Error: releasing the leg before securing clinch — opponent recovers.', 'Both', 'Sport', 'None', false, 'mt-counter', 'sport-muaythai'),
  ('tech-mt-084', 84, 'Counter-Attack', 'Kick Counter', 'Catch Round Kick → Counter Kick', 'mt-catch-round-kick-counter-kick', 'Pin opponent''s body round kick and counter with kick to their standing leg or body.', 'Advanced', 'Window is small — counter must be immediate. Error: hesitating after catch — opponent regains base.', 'Both', 'Sport', 'None', false, 'mt-counter', 'sport-muaythai'),
  ('tech-mt-085', 85, 'Counter-Attack', 'Punch Counter', 'Slip Jab → Cross Counter', 'mt-slip-jab-cross-counter', 'Slip outside the jab and fire rear cross while opponent''s arm is extended.', 'Intermediate', 'Classic counter. Timing: cross fires as jab is at full extension. Error: countering after jab is retracted.', 'Both', 'Both', 'None', false, 'mt-counter', 'sport-muaythai'),
  ('tech-mt-086', 86, 'Counter-Attack', 'Punch Counter', 'Parry Cross → Body Kick', 'mt-parry-cross-body-kick', 'Parry the rear hand cross offline with lead hand and immediately fire body kick with rear leg.', 'Intermediate', 'Opponent''s weight shifts forward on cross — body is exposed. Counter must flow without pause.', 'Both', 'Sport', 'None', false, 'mt-counter', 'sport-muaythai'),
  ('tech-mt-087', 87, 'Counter-Attack', 'Teep Counter', 'Lean Back Teep → Advance', 'mt-lean-back-teep-advance', 'Lean back to avoid head kick then immediately fire teep as opponent''s weight is forward after kick.', 'Advanced', 'Opponent is off-balance post-kick. Error: pausing before advancing — opponent recovers stance.', 'Both', 'Sport', 'None', false, 'mt-counter', 'sport-muaythai'),
  ('tech-mt-088', 88, 'Counter-Attack', 'Elbow Counter', 'Elbow vs. Head Kick', 'mt-elbow-vs-head-kick', 'Duck under incoming head kick and fire upward elbow as opponent''s leg passes overhead.', 'Expert', 'Extremely high risk if timed wrong — kick lands instead. Specialist technique for experienced fighters.', 'Professional', 'Sport', 'None', false, 'mt-counter', 'sport-muaythai'),
  ('tech-mt-089', 89, 'Counter-Attack', 'Clinch Counter', 'Block Low Kick → Enter Clinch', 'mt-block-low-kick-enter-clinch', 'After blocking low kick, step in aggressively and tie up — controls opponent when they''re on one leg.', 'Intermediate', 'Works best when opponent throws power low kick and is momentarily off balance.', 'Both', 'Both', 'None', false, 'mt-counter', 'sport-muaythai'),
  ('tech-mt-090', 90, 'Concept', 'Range', 'Range Management', 'mt-range-management', 'The four fighting ranges: long (kicks), mid (punches/knees), short (elbows), clinch. Controlling which range the fight occurs in.', 'Beginner', 'Understand which weapons work at which range. Teep controls long range; cross controls mid; elbows short.', 'Both', 'Both', 'None', false, 'mt-concepts', 'sport-muaythai'),
  ('tech-mt-091', 91, 'Concept', 'Rhythm', 'Rhythm and Timing', 'mt-rhythm-and-timing', 'Varying attack tempo — fast-fast-slow, broken rhythm, delayed attacks — to disrupt opponent''s defensive timing.', 'Intermediate', 'Most knockouts come from timing errors, not power alone. Train rhythm as deliberately as technique.', 'Both', 'Sport', 'None', false, 'mt-concepts', 'sport-muaythai'),
  ('tech-mt-092', 92, 'Concept', 'Combination', 'Combination Theory (High-Low)', 'mt-combination-theory-high-low', 'Mixing high and low targets in combinations forces opponent to defend two levels simultaneously, opening both.', 'Intermediate', 'Body kick sets up head kick; jab to face sets up body kick. Never attack one level repeatedly.', 'Both', 'Both', 'None', false, 'mt-concepts', 'sport-muaythai'),
  ('tech-mt-093', 93, 'Concept', 'Feinting', 'Feinting Principles', 'mt-feinting-principles', 'False attacks that trigger defensive reactions — creating openings for the real attack.', 'Intermediate', 'Feint must be realistic enough to trigger defense. Error: feinting without follow-up — opponent learns to ignore it.', 'Both', 'Sport', 'None', false, 'mt-concepts', 'sport-muaythai'),
  ('tech-mt-094', 94, 'Concept', 'Power', 'Hip Rotation in Striking', 'mt-hip-rotation-in-striking', 'All Muay Thai power originates from hip rotation — the hip drives the shoulder, which drives the arm or leg.', 'Beginner', 'Foundation concept. If a student understands hip rotation, every technique improves simultaneously.', 'Both', 'Both', 'None', false, 'mt-concepts', 'sport-muaythai'),
  ('tech-mt-095', 95, 'Concept', 'Strategy', 'Pressure Fighting', 'mt-pressure-fighting', 'Constant forward movement, high output, cutting ring — suits fighters with good chin and cardio.', 'Intermediate', 'Effective but high energy cost. Works best when combined with good guard to absorb counters.', 'Both', 'Sport', 'None', false, 'mt-concepts', 'sport-muaythai'),
  ('tech-mt-096', 96, 'Concept', 'Strategy', 'Counter Fighting', 'mt-counter-fighting', 'Allow opponent to attack, create openings through their aggression, and punish with precise counters.', 'Advanced', 'Requires reading and patience. Dangerous if opponent is disciplined and doesn''t over-commit.', 'Both', 'Sport', 'None', false, 'mt-concepts', 'sport-muaythai'),
  ('tech-mt-097', 97, 'Concept', 'Scoring', 'Muay Thai Scoring System', 'mt-muay-thai-scoring-system', 'Judges prioritize clean effective techniques, aggression, and ring generalship — not just volume of strikes.', 'Intermediate', 'A hard round kick to the body outscores ten jabs in Thai scoring. Understand what judges value.', 'Both', 'Sport', 'None', false, 'mt-concepts', 'sport-muaythai'),
  ('tech-mt-098', 98, 'Concept', 'Matchup', 'Orthodox vs. Southpaw Strategy', 'mt-orthodox-vs-southpaw-strategy', 'Open-stance matchup: both lead feet are aligned. Jab to outside, left kick to open side, inside low kick exposed.', 'Advanced', 'The most common matchup problem fighters are unprepared for. Train explicitly.', 'Both', 'Sport', 'None', false, 'mt-concepts', 'sport-muaythai'),
  ('tech-mt-099', 99, 'Concept', 'Culture', 'Wai Kru Ram Muay', 'mt-wai-kru-ram-muay', 'Traditional pre-fight ritual dance honoring teachers and the sport. Expression of respect and mental preparation.', 'Beginner', 'Cultural cornerstone of authentic Muay Thai. Every student should learn the basic form.', 'Both', 'Both', 'None', false, 'mt-concepts', 'sport-muaythai'),
  ('tech-mt-100', 100, 'Concept', 'Conditioning', 'Shin Conditioning', 'mt-shin-conditioning', 'Progressive hardening of the shin through repeated impact — kicks become more powerful and less painful to land.', 'Beginner', 'Gradual process. Start with light bag work; increase over months. Error: trying to condition too fast — stress fractures.', 'Both', 'Both', 'None', false, 'mt-concepts', 'sport-muaythai'),
  ('tech-mt-101', 101, 'Concept', 'Defense', 'Submission Defense Principles', 'mt-submission-defense-principles', 'General Muay Thai defense philosophy: move the target, block the weapon, counter immediately.', 'Beginner', 'Defense that doesn''t include a counter is just survival. Train all three responses together.', 'Both', 'Both', 'None', false, 'mt-concepts', 'sport-muaythai'),
  ('tech-mt-102', 102, 'Drill', 'Solo', 'Shadow Boxing', 'mt-shadow-boxing', 'Freestyle solo drilling of techniques, footwork, and combinations at full speed without a partner.', 'Beginner', 'Most underutilized training tool. Visualize a real opponent. Error: moving randomly — train specific scenarios.', 'Both', 'Both', 'None', false, 'mt-drills', 'sport-muaythai'),
  ('tech-mt-103', 103, 'Drill', 'Solo', 'Skipping Rope', 'mt-skipping-rope', 'Fundamental conditioning and footwork drill building rhythm, calf strength, and aerobic base.', 'Beginner', '10+ minutes daily. Build to 3-minute rounds matching fight round length. Error: skipping flatfooted.', 'Both', 'Both', 'None', false, 'mt-drills', 'sport-muaythai'),
  ('tech-mt-104', 104, 'Drill', 'Solo', 'Heavy Bag Rounds', 'mt-heavy-bag-rounds', 'Strike the bag in structured rounds developing power, timing, and stamina.', 'Beginner', 'Vary targets and technique types each round. Error: just throwing power shots — trains bad habits under fatigue.', 'Both', 'Both', 'None', false, 'mt-drills', 'sport-muaythai'),
  ('tech-mt-105', 105, 'Drill', 'Solo', 'Inversion & Hip Flexibility', 'mt-inversion-hip-flexibility', 'Daily stretching routine targeting hip flexors, hamstrings, and hip rotators — required for high kicks.', 'Beginner', 'Consistency matters more than intensity. 10 minutes daily beats 1 hour weekly.', 'Both', 'Both', 'None', false, 'mt-drills', 'sport-muaythai'),
  ('tech-mt-106', 106, 'Drill', 'Solo', 'Combination Drilling (Solo)', 'mt-combination-drilling-solo', 'Drill specific combinations on bag or in shadow — repeat until the sequence is automatic.', 'Beginner', '5-10 reps of each combo, both sides. Error: drilling only dominant side — creates predictability.', 'Both', 'Both', 'None', false, 'mt-drills', 'sport-muaythai'),
  ('tech-mt-107', 107, 'Drill', 'Partner', 'Pad Work', 'mt-pad-work', 'Trainer holds Thai pads while student works combinations, timing, and power at realistic speed.', 'Beginner', 'Best feedback loop in Muay Thai. Pad holder sets rhythm and distance. Error: pad holder not calling combos — student becomes passive.', 'Both', 'Both', 'None', false, 'mt-drills', 'sport-muaythai'),
  ('tech-mt-108', 108, 'Drill', 'Partner', 'Pummeling (Clinch Position Drilling)', 'mt-pummeling-clinch-position-drilling', 'Rhythmic in-out clinch position battle — both fighters compete for inside position without knees.', 'Intermediate', 'Develops sensitivity for inside position control. Flow, don''t force.', 'Both', 'Both', 'None', false, 'mt-drills', 'sport-muaythai'),
  ('tech-mt-109', 109, 'Drill', 'Partner', 'Clinch Sparring', 'mt-clinch-sparring', 'Live clinch with knees and throws allowed — focused on clinch position, not full sparring.', 'Intermediate', 'Crucial for Thai-style Muay Thai. Separated from full sparring to allow technical development.', 'Both', 'Both', 'None', false, 'mt-drills', 'sport-muaythai'),
  ('tech-mt-110', 110, 'Drill', 'Partner', 'Timing Drill (Slip and Counter)', 'mt-timing-drill-slip-and-counter', 'Partner throws slow jabs; defender slips and counters. Gradually increase speed.', 'Intermediate', 'Build the reaction before the speed. Error: jumping straight to fast — builds flinching not slipping.', 'Both', 'Both', 'None', false, 'mt-drills', 'sport-muaythai'),
  ('tech-mt-111', 111, 'Drill', 'Partner', 'Catch and Counter Drill', 'mt-catch-and-counter-drill', 'Partner throws kicks; defender catches and immediately counters. Builds catch reflex and counter flow.', 'Intermediate', 'Catch and counter must be one motion. Error: pausing between catch and counter — opponent recovers.', 'Both', 'Sport', 'None', false, 'mt-drills', 'sport-muaythai'),
  ('tech-mt-112', 112, 'Drill', 'Partner', 'Technical Sparring', 'mt-technical-sparring', 'Light-contact sparring with emphasis on technique, range, and timing — not power.', 'Intermediate', 'Best learning environment. Rule: if you used strength, reset. Error: escalating to hard sparring — injuries end sessions.', 'Both', 'Both', 'None', false, 'mt-drills', 'sport-muaythai'),
  ('tech-mt-113', 113, 'Drill', 'Partner', 'Specific Sparring (Kick Only)', 'mt-specific-sparring-kick-only', 'Sparring restricted to one weapon — kicks only, elbows only, etc. Forces development of that weapon.', 'Intermediate', 'Constraint-based training builds skill faster than open sparring in early stages.', 'Both', 'Sport', 'None', false, 'mt-drills', 'sport-muaythai'),
  ('tech-mt-114', 114, 'Drill', 'Conditioning', 'Neck Bridge', 'mt-neck-bridge', 'Strengthening exercise for neck muscles — critical for clinch resistance and absorbing head shots.', 'Beginner', 'Progress slowly. Strong neck reduces knockout risk. Error: rushing to full bridge without building baseline strength.', 'Both', 'Both', 'None', false, 'mt-drills', 'sport-muaythai'),
  ('tech-mt-115', 115, 'Drill', 'Conditioning', 'Periodization for Competition', 'mt-periodization-for-competition', 'Structure of 8–12 week camp: high volume early, increase intensity mid-camp, sharpen and taper final 2 weeks.', 'Advanced', 'Arrives at fight fresh but sharp. Error: going hard until fight week — overtrained and slow.', 'Professional', 'Sport', 'None', false, 'mt-drills', 'sport-muaythai')
